$ErrorActionPreference='Stop'
function CheckStatus($expected,$label){$s=Invoke-RestMethod 'http://127.0.0.1:8080/api/voice/status' -TimeoutSec 5; if(-not $s.success){throw "$label status failed"}; "$label enabled=$($s.enabled) state=$($s.state) turn=$($s.turn.id)"; if($expected -ne $null -and $s.enabled -ne $expected){throw "$label expected enabled=$expected"}; return $s}
CheckStatus $false 'initial' | Out-Null
for($i=1;$i -le 4;$i++){$a=Invoke-RestMethod 'http://127.0.0.1:8080/api/voice/session' -Method Post -ContentType 'application/json' -Body '{"enabled":true}' -TimeoutSec 8; "start$i success=$($a.success) enabled=$($a.enabled) state=$($a.state)"; if(-not $a.success -or -not $a.enabled){throw "start $i failed"}; Start-Sleep -Milliseconds 700; CheckStatus $true "active$i" | Out-Null; $z=Invoke-RestMethod 'http://127.0.0.1:8080/api/voice/session' -Method Post -ContentType 'application/json' -Body '{"enabled":false}' -TimeoutSec 8; "stop$i success=$($z.success) enabled=$($z.enabled) state=$($z.state)"; if(-not $z.success -or $z.enabled){throw "stop $i failed"}; Start-Sleep -Milliseconds 300; CheckStatus $false "after$i" | Out-Null}
try {$bad=Invoke-RestMethod 'http://127.0.0.1:8080/api/voice/session' -Method Post -ContentType 'application/json' -Body '{"enabled":"not-a-bool"}' -TimeoutSec 5; "bad-payload accepted=$($bad.success) enabled=$($bad.enabled)"} catch {"bad-payload rejected: $($_.Exception.Message)"}
